import { readFileSync } from "node:fs";
import { expect, test } from "@playwright/test";
import { waitForCardOpen, waitForMap } from "./helpers";

// Generated by scripts/build-metro.mjs (pretest) from content/metro/stations.json.
const metro = JSON.parse(readFileSync("app/metro/metro.public.json", "utf8")) as {
  stations: { id: string; slug?: string; name: string }[];
  stores: { stationId: string }[];
};
const noShop = metro.stations.filter((s) => !metro.stores.some((x) => x.stationId === s.id));

test("F-5 content stations without hero shops exist (regression guard for the list[0] crash)", () => {
  expect(noShop.length).toBeGreaterThan(0);
  for (const s of noShop) expect(s.slug, s.id).toBeTruthy();
});

for (const s of noShop) {
  test(`F-5 ${s.id}: marker opens a non-blank card that links to /metro/${s.slug}`, async ({ page }) => {
    const errors: string[] = [];
    page.on("pageerror", (e) => errors.push(e.message));
    await page.goto("/?reduce=1");
    await waitForMap(page);
    // Photo targets take priority where targets overlap. Click an exposed point
    // of the centred station target using real pointer input.
    await page.locator('#vp').scrollIntoViewIfNeeded();
    const hit = page.getByTestId(`metro-pin-${s.id}`).locator('.hit');
    const point = await hit.evaluate(el => {
      const r = el.getBoundingClientRect();
      for (let y = 4; y < r.height; y += 4) {
        for (let x = 4; x < r.width; x += 4) {
          if (document.elementFromPoint(r.x + x, r.y + y) === el) return { x: r.x + x, y: r.y + y };
        }
      }
      return null;
    });
    expect(point, `${s.id} has an exposed pointer target`).not.toBeNull();
    await page.mouse.click(point!.x, point!.y);
    await waitForCardOpen(page);
    await expect(page.locator("#card .soonbody")).not.toBeEmpty();
    await expect(page.locator("#cardTitle")).toContainText(s.name);
    const link = page.getByTestId(`metro-food-link-${s.id}`);
    await expect(link).toBeVisible();
    await expect(link).toHaveAttribute("href", `/metro/${s.slug}`);
    const [resp] = await Promise.all([
      page.waitForResponse((r) => new URL(r.url()).pathname === `/metro/${s.slug}` && r.request().resourceType() === "document"),
      link.click(),
    ]);
    expect(resp.status()).toBe(200);
    await expect(page).toHaveURL(new RegExp(`/metro/${s.slug}$`));
    expect(errors).toEqual([]);
  });
}

for (const viewport of [{ width: 1280, height: 720 }, { width: 390, height: 844 }]) {
  test(`content-only targets and home framing at ${viewport.width}`, async ({ page }) => {
    await page.setViewportSize(viewport);
    await page.goto('/?reduce=1');
    await waitForMap(page);
    await page.locator('#vp').scrollIntoViewIfNeeded();
    await page.evaluate(() => document.fonts.ready);
    const frame = (await page.locator('#vp').boundingBox())!;
    for (const station of metro.stations) {
      const dot = await page.getByTestId(`metro-pin-${station.id}`).evaluate(el => {
        const r = el.getBoundingClientRect();
        return { x: r.x, y: r.y };
      });
      expect(dot.x, station.id).toBeGreaterThan(frame.x);
      expect(dot.x, station.id).toBeLessThan(frame.x + frame.width);
      expect(dot.y, station.id).toBeGreaterThan(frame.y);
      expect(dot.y, station.id).toBeLessThan(frame.y + frame.height);
    }
    const labelsInside = await page.locator('#stdots text').evaluateAll(labels => {
      const frame = document.querySelector('#vp')!.getBoundingClientRect();
      return labels.every(el => {
        const r = el.getBoundingClientRect();
        return r.left >= frame.left && r.right <= frame.right && r.top >= frame.top && r.bottom <= frame.bottom;
      });
    });
    expect(labelsInside).toBe(true);
    const gutingClear = await page.locator('#stdots text').filter({ hasText: /^古亭$/ }).evaluate(el => {
      const label = el.getBoundingClientRect();
      return [...document.querySelectorAll('.pin:not(.content-only) .ph')].every(photo => {
        const r = photo.getBoundingClientRect();
        // Photo heads are circles; their bounding-box corners are transparent.
        const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
        const x = Math.max(label.left, Math.min(label.right, cx));
        const y = Math.max(label.top, Math.min(label.bottom, cy));
        return Math.hypot(x - cx, y - cy) >= r.width / 2;
      });
    });
    expect(gutingClear).toBe(true);
    for (const station of noShop) {
      const pin = page.getByTestId(`metro-pin-${station.id}`);
      await expect(pin.locator('.ph')).toBeHidden();
      const hit = (await pin.locator('.hit').boundingBox())!;
      expect(hit.width).toBeGreaterThanOrEqual(44);
      expect(hit.height).toBeGreaterThanOrEqual(44);
      const dot = await pin.boundingBox();
      expect(hit.x + hit.width / 2).toBeCloseTo(dot!.x, 0);
      expect(hit.y + hit.height / 2).toBeCloseTo(dot!.y, 0);
      await pin.focus();
      await expect(pin.locator('.hit')).toHaveCSS('outline-style', 'dashed');
      await expect(pin.locator('.hit')).toHaveCSS('outline-width', '3px');
    }
    if (viewport.width === 1280) {
      const hit = (await page.getByTestId('metro-pin-shilin').locator('.hit').boundingBox())!;
      expect(hit.y).toBeGreaterThanOrEqual(frame.y);
      expect(hit.x).toBeGreaterThanOrEqual(frame.x);
      expect(hit.x + hit.width).toBeLessThanOrEqual(frame.x + frame.width);
      expect(hit.y + hit.height).toBeLessThanOrEqual(frame.y + frame.height);
    }
    // An overlapping content target must never intercept a photo target.
    const overlaps = await page.locator('.pin:not(.content-only) .hit').evaluateAll(photos => {
      const empty = [...document.querySelectorAll('.pin.content-only .hit')];
      return photos.flatMap(photo => empty.flatMap(other => {
        const a = photo.getBoundingClientRect(), b = other.getBoundingClientRect();
        const l = Math.max(a.left, b.left), r = Math.min(a.right, b.right);
        const t = Math.max(a.top, b.top), bottom = Math.min(a.bottom, b.bottom);
        if (l >= r || t >= bottom) return [];
        const target = document.elementFromPoint((l + r) / 2, (t + bottom) / 2);
        // Rectangular bounds include corners outside the rounded photo target.
        const x = (l + r) / 2, y = (t + bottom) / 2;
        const radius = 23, cy = Math.max(a.top + radius, Math.min(a.bottom - radius, y));
        if (Math.hypot(x - (a.left + a.width / 2), y - cy) >= radius - 1) return [];
        return [!target?.closest('.pin.content-only')];
      }));
    });
    for (const photoWins of overlaps) expect(photoWins).toBe(true);
  });
}
